// str.join: "Concatenate any number of strings. The string whose method is called is
// inserted in between each given string. The result is returned as a new string."
// Example: '.'.join(['ab', 'pq', 'rs']) -> 'ab.pq.rs'
function StrJoin(parts: seq<string>, sep: string): string {
  if |parts| == 0 then ""
  else if |parts| == 1 then parts[0]
  else parts[0] + sep + StrJoin(parts[1..], sep)
}

// list: "Built-in mutable sequence. If no argument is given, the constructor creates a
// new empty list. The argument must be an iterable if specified."
// list(iterable) yields the items of the iterable, in order.
function PyList<T>(items: seq<T>): seq<T> {
  items
}

// filter: "Return an iterator yielding those items of iterable for which
// function(item) is true."
function Filter<T>(items: seq<T>, f: T -> bool): seq<T> {
  if |items| == 0 then []
  else if f(items[0]) then [items[0]] + Filter(items[1..], f)
  else Filter(items[1..], f)
}

// Iterating over a str yields its characters, each as a one-character string.
function StrChars(s: string): seq<string> {
  if |s| == 0 then [] else [[s[0]]] + StrChars(s[1..])
}

// `x in s` for strings: "True if an item of s is equal to x"; for str, membership is
// a substring test. For a one-character x this is "the character occurs in s".
predicate StrContains(s: string, sub: string) {
  exists i :: 0 <= i <= |s| - |sub| && s[i..i + |sub|] == sub
}
```

