// sum: "Return the sum of a 'start' value (default: 0) plus an iterable of numbers.
//       When the iterable is empty, return the start value."
function SumStart(xs: seq<int>, start: int): int
  decreases |xs|
{
  if |xs| == 0 then start else SumStart(xs[..|xs|-1], start) + xs[|xs|-1]
}

// sum with the default start value: "'start' value (default: 0)"
function Sum(xs: seq<int>): int
{
  SumStart(xs, 0)
}

// ord: "If the argument is a one-character string, return the Unicode code point of that character."
function Ord(c: char): int
{
  c as int
}

// Unicode property "cased character" (used by str.isupper); full Unicode tables are not modeled.
// For ASCII, the cased characters are exactly the letters A-Z and a-z.
function {:axiom} CharIsCased(c: char): bool
  ensures (c as int) < 128 ==> (CharIsCased(c) <==> (('A' <= c <= 'Z') || ('a' <= c <= 'z')))

// Unicode property "uppercase character" (used by str.isupper).
// For ASCII, the uppercase characters are exactly A-Z. Uppercase characters are cased.
function {:axiom} CharIsUppercase(c: char): bool
  ensures (c as int) < 128 ==> (CharIsUppercase(c) <==> ('A' <= c <= 'Z'))
  ensures CharIsUppercase(c) ==> CharIsCased(c)

// str.isupper: "A string is uppercase if all cased characters in the string are
//               uppercase and there is at least one cased character in the string."
predicate StrIsUpper(s: string)
{
  (forall i :: 0 <= i < |s| && CharIsCased(s[i]) ==> CharIsUppercase(s[i]))
  && (exists i :: 0 <= i < |s| && CharIsCased(s[i]))
}
