}

// Helper: numeric value of a decimal digit character.
function DigitValue(c: char): int
  requires IsDigitChar(c)
{
  (c as int) - ('0' as int)
}

// Helper: decimal digits of a non-negative integer, with no leading zeros ("0" for 0).
function NatToDecimal(n: int): string
  requires n >= 0
  decreases n
