// Extended number domain: Python float/int values modeled as `real`, plus positive infinity.
// Needed because the convention float -> real has no representation for math.inf.
datatype ExtReal = PosInf | Finite(value: real)

// math.inf: "A floating-point positive infinity. (For negative infinity, use -math.inf.)"
// math.inf compares greater than every finite float/int.
const MathInf: ExtReal := PosInf

// Embedding of a Python int into the extended number domain (int compares with float by value).
function IntToExt(x: int): ExtReal
{
  Finite(x as real)
}

// Python `<` between numbers (int/float/inf): ordinary numeric order, inf greater than all finite values.
predicate ExtLt(a: ExtReal, b: ExtReal)
{
  match (a, b)
  case (PosInf, _) => false
  case (Finite(_), PosInf) => true
  case (Finite(x), Finite(y)) => x < y
}

// Python `<=` between numbers.
predicate ExtLe(a: ExtReal, b: ExtReal)
{
  !ExtLt(b, a)
}

// min: "With two or more positional arguments, return the smallest argument."
// CPython returns the first argument among equal minima (it replaces the candidate only when strictly smaller).
function Min(a: ExtReal, b: ExtReal): ExtReal
{
  if ExtLt(b, a) then b else a
}

// min over Python ints:
// "With two or more positional arguments, return the smallest argument."
function MinInt(a: int, b: int): int
{
  if b < a then b else a
}
