// Library theory for: str.strip, str.lower, str.split, str.isalpha, sum, list.append
// Modeling assumption: character classes (whitespace, case, alphabetic) are restricted
// to ASCII. The program's docstring says inputs contain only letters and spaces.

// str.isspace (used by strip/split): "split on any whitespace character
// (including \n \r \t \f and spaces)". ASCII whitespace per Python: ' ', \t, \n, \v, \f, \r,
// plus \x1c-\x1f.
predicate IsSpaceChar(c: char)
{
  c == ' ' || c == '\t' || c == '\n' || c == '\r'
  || c as int == 11 || c as int == 12
  || (28 <= c as int <= 31)
}

// str.strip: "Return a copy of the string with leading and trailing whitespace removed."
function StrLStrip(s: string): string
  decreases |s|
{
  if |s| > 0 && IsSpaceChar(s[0]) then StrLStrip(s[1..]) else s
}

function StrRStrip(s: string): string
  decreases |s|
{
  if |s| > 0 && IsSpaceChar(s[|s| - 1]) then StrRStrip(s[..|s| - 1]) else s
}

function StrStrip(s: string): string
{
  StrRStrip(StrLStrip(s))
}

// str.lower: "Return a copy of the string converted to lowercase." (ASCII case mapping)
function CharLower(c: char): char
{
  if 'A' <= c <= 'Z' then (c as int - 'A' as int + 'a' as int) as char else c
}

function StrLower(s: string): string
  decreases |s|
{
  if |s| == 0 then "" else [CharLower(s[0])] + StrLower(s[1..])
}

// str.split (sep=None): "will split on any whitespace character ... and will discard
// empty strings from the result." "Splitting starts at the front of the string and works to the end."
function StrSplitAux(s: string, cur: string): seq<string>
  decreases |s|
{
  if |s| == 0 then
    (if |cur| == 0 then [] else [cur])
  else if IsSpaceChar(s[0]) then
    (if |cur| == 0 then StrSplitAux(s[1..], "") else [cur] + StrSplitAux(s[1..], ""))
  else
    StrSplitAux(s[1..], cur + [s[0]])
}

function StrSplit(s: string): seq<string>
{
  StrSplitAux(s, "")
}

